create extension if not exists pgcrypto;
create table if not exists organizations (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table if not exists simpro_connections (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), name text not null, base_url text not null, company_id text not null, encrypted_refresh_token text, encrypted_access_token text, token_expires_at timestamptz, status text not null default 'pending', last_error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), last_checked_at timestamptz);
create index if not exists simpro_connections_org_idx on simpro_connections(organization_id);
create table if not exists oauth_states (state text primary key, organization_id uuid not null, connection_id uuid not null, code_verifier text not null, expires_at timestamptz not null);
create table if not exists audit_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null, actor_id text, connection_id uuid, action text not null, resource text, resource_id text, success boolean not null, request_id text not null, metadata jsonb, created_at timestamptz not null default now());
create table if not exists export_jobs (id uuid primary key default gen_random_uuid(), organization_id uuid not null, connection_id uuid not null, resource text not null, format text not null, status text not null default 'queued', filters jsonb, file_path text, error text, created_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists sync_runs (id uuid primary key default gen_random_uuid(), organization_id uuid not null, connection_id uuid not null, resource text not null, status text not null default 'queued', cursor text, rows_processed integer not null default 0, error text, created_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists idempotency_keys (organization_id uuid not null, key text not null, operation text not null, response jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,key,operation));
create table if not exists normalized_records (organization_id uuid not null, connection_id uuid not null, resource text not null, external_id text not null, payload jsonb not null, source_updated_at timestamptz, synced_at timestamptz not null default now(), primary key(organization_id,connection_id,resource,external_id));
create index if not exists normalized_records_lookup_idx on normalized_records(organization_id,resource);
